#!/usr/bin/env bash
#
# AiPBX first-boot installer inside the container (docker/README.md).
#
# Runs the project's own install.sh exactly once, then the three things a
# container needs and a bare host does not. Idempotent: a marker on the state
# volume makes every later boot a no-op, so restarts and image rebuilds keep
# the deployment they created.
#
# Nothing here re-implements provisioning: the source is the same checkout a
# `sudo bash install.sh` user gets, and every password is generated by that
# script per deployment.
set -u
set -o pipefail

# --- the compose variables --------------------------------------------------
# systemd starts this unit with its own minimal environment, not the container's:
# `AIPBX_FQDN` and friends are in PID 1's environment (/proc/1/environ), which is
# where Docker put them. Without this the installer ignored AIPBX_FQDN and fell
# back to its interactive default.
container_env() {
    local line
    line="$(tr '\0' '\n' < /proc/1/environ 2>/dev/null | grep -m1 -a "^${1}=" || true)"
    printf '%s' "${line#*=}"
}
# compose value first, this shell's own environment second, then the default.
env_or() {
    local value
    value="$(container_env "$1")"
    if [[ -z "$value" ]]; then
        value="${!1:-}"
    fi
    printf '%s' "${value:-${2:-}}"
}

REPO="$(env_or AIPBX_REPO https://github.com/mahirgul/AiPBX.git)"
REF="$(env_or AIPBX_REF '')"
SRC="$(env_or AIPBX_INSTALL_DIR /opt/aipbx)"
STATE="$(env_or AIPBX_STATE_DIR /var/lib/aipbx)"
LOG="$(env_or AIPBX_INSTALL_LOG /var/log/aipbx-install.log)"
RTP_RANGE="$(env_or AIPBX_RTP_RANGE '')"
MARKER="$STATE/.installed"
# The installer's non-interactive switch: a name supplied here means no FQDN
# prompt. A .local name also means self-signed TLS, so no other question either.
AIPBX_FQDN="$(env_or AIPBX_FQDN aipbx.local)"
export AIPBX_FQDN

# --- make the first boot followable -----------------------------------------
# A unit's output goes to the journal, which Docker's log driver does not see
# (systemd owns PID 1's stdout, and points it at /dev/null). So it goes to a
# file as well; the README watches that file or the journal.
exec > >(tee -a "$LOG") 2>&1

log() { echo "aipbx-bootstrap: $*"; }

# --- the kernel is shared with the host -------------------------------------
# install.sh configures firewalld. Inside a container that service cannot stay
# up, but the rules it loads live in the *host's* netfilter, where they reject
# the very ports Docker publishes — a container that cannot be reached and a
# host whose other services lose their ports. Dropping the table once firewalld
# is no longer managing it is what makes a published port answer.
drop_dead_firewall() {
    if ! systemctl is-active --quiet firewalld 2>/dev/null; then
        nft delete table inet firewalld 2>/dev/null || true
        systemctl disable --quiet firewalld 2>/dev/null || true
    fi
}

# /var/www/html is a symlink to the installed web/ (install.sh). A rebuilt
# image gets a fresh container filesystem, where the install is skipped by the
# marker but Apache still needs the link.
ensure_layout() {
    if [[ -d "$SRC/web" && ! -L /var/www/html && ! -e /var/www/html ]]; then
        ln -sfn "$SRC/web" /var/www/html
        log "re-linked /var/www/html → $SRC/web"
    fi
}

# --- the scheduler -----------------------------------------------------------
# install.sh writes /etc/cron.d/aipbx: the 02:30 backup, phone discovery every
# five minutes, queue sync, retention. The file lives on the /etc volume and
# survives a rebuild; the daemon does not — it comes from the image — and the
# systemd enablement is a link in the volume's /etc/systemd, which a deployment
# created before this image carried cron never got. Such a deployment comes
# back up with every scheduled job silently not running, so the scheduler is
# re-armed on every boot, not only on the one that installs.
ensure_cron() {
    if [[ ! -f /etc/cron.d/aipbx ]]; then
        log "WARNING: /etc/cron.d/aipbx is missing — no backup, discovery or retention job is scheduled (install.sh writes it)"
        return 0
    fi
    if systemctl enable --now cron >/dev/null 2>&1 && systemctl is-active --quiet cron; then
        log "cron is running (backup 02:30, phone discovery every 5 min, retention)"
    else
        log "WARNING: cron did not start — the backup, phone discovery and retention jobs will not run"
    fi
}

drop_dead_firewall

if [[ -f "$MARKER" ]]; then
    ensure_layout
    ensure_cron
    log "already installed ($MARKER) — nothing to do"
    exit 0
fi

# --- source -----------------------------------------------------------------
mkdir -p "$STATE" "$(dirname "$LOG")"
if [[ ! -f "$SRC/web/config.php" ]]; then
    log "cloning $REPO into $SRC"
    mkdir -p "$SRC"
    if ! git clone --quiet "$REPO" "$SRC"; then
        log "clone failed — check AIPBX_REPO and the container's network"
        exit 1
    fi
fi

# The installer's own default: the newest release tag, so an install is a
# release and not a moving branch. AIPBX_REF=main (or a tag) overrides it.
if [[ -z "$REF" ]]; then
    REF="$(git -C "$SRC" tag -l 'v[0-9]*.[0-9]*.[0-9]*' --sort=-v:refname | head -1)"
fi
REF="${REF:-main}"
if ! git -C "$SRC" checkout --quiet --force "$REF"; then
    log "cannot check out $REF in $SRC"
    exit 1
fi
log "installing AiPBX $REF"

# --- install ----------------------------------------------------------------
# AIPBX_FQDN comes from the compose file: it is what makes the installer
# non-interactive (a .local name means self-signed TLS, so no Let's Encrypt
# questions and nothing to answer on a terminal that does not exist).
export DEBIAN_FRONTEND=noninteractive HOME=/root
log "running install.sh (a few minutes to half an hour on a fresh host; output follows)"
# No tee here: this script's stdout already goes to the log file and to Docker.
if ! bash "$SRC/install.sh" </dev/null 2>&1; then
    log "install.sh FAILED — see $LOG (last lines follow)"
    tail -30 "$LOG" | sed 's/^/    /'
    exit 1
fi

# install.sh installs and configures firewalld on the way through. In a
# container its table is the host's and only the PBX ports survive in it — the
# host's other services lose theirs. Drop it again and leave host firewalling
# to the host (docker/README.md, Security).
if systemctl is-active --quiet firewalld 2>/dev/null; then
    systemctl disable --now firewalld >/dev/null 2>&1 || true
    log "firewalld stopped and disabled (its rules belong to the host)"
fi
drop_dead_firewall

# The installer prints every generated credential and writes the same summary
# to /root/aipbx-credentials.txt (the admin password is only there: the portal
# keeps a hash of it). /root is not a volume, so a copy goes on the state
# volume where the README points.
if install -m 0600 -o root -g root /root/aipbx-credentials.txt "$STATE/credentials.txt" 2>/dev/null; then
    log "credentials: $STATE/credentials.txt (also printed above)"
else
    log "WARNING: /root/aipbx-credentials.txt is missing — the credentials are in the output above"
fi

# --- the RTP window ---------------------------------------------------------
# Asterisk's default range is 10000–12999, and Docker runs a userland proxy per
# published port: publishing a 3000-port range means 3000 processes. The
# compose file publishes a 200-port window instead, and this sets both sides of
# it — the portal's own setting (so its next Apply keeps it) and rtp.conf, with
# the restart a range change needs. A failure here is reported, not hidden:
# calls would have one-way audio without it.
apply_rtp_window() {
    [[ -n "$RTP_RANGE" ]] || return 0
    local start="${RTP_RANGE%-*}" end="${RTP_RANGE#*-}"
    if [[ ! "$start" =~ ^[0-9]+$ || ! "$end" =~ ^[0-9]+$ || "$end" -le "$start" ]]; then
        log "WARNING: AIPBX_RTP_RANGE='$RTP_RANGE' is not a range like 10000-10199 — left as it was"
        return 0
    fi

    # Read, not source: the file holds values with spaces in them.
    local db_user db_pass db_name
    db_user="$(grep -m1 '^DB_USER=' /etc/ai-pbx.env | cut -d= -f2-)"
    db_pass="$(grep -m1 '^DB_PASS=' /etc/ai-pbx.env | cut -d= -f2-)"
    db_name="$(grep -m1 '^DB_NAME=' /etc/ai-pbx.env | cut -d= -f2-)"

    if ! mysql -h 127.0.0.1 -u"$db_user" -p"$db_pass" "$db_name" -e "
            INSERT INTO sys_settings (setting_key, setting_value)
                 VALUES ('rtp_start', '$start'), ('rtp_end', '$end')
            ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value);" 2>/dev/null; then
        log "WARNING: could not set the RTP range in the portal — set it in PBX settings → RTP (${start}-${end})"
        return 0
    fi
    # The portal owns rtp.conf; generate it from the settings just written.
    if ! php "$SRC/web/src/asterisk_sync.php" >>"$LOG" 2>&1; then
        log "WARNING: config sync failed after setting the RTP range — see $LOG"
        return 0
    fi
    asterisk -rx "core restart now" >>"$LOG" 2>&1 || true
    log "RTP window set to ${start}-${end} (the ports compose publishes)"
}

apply_rtp_window

# --- let Asterisk come back before the self test ----------------------------
# The RTP window above restarts Asterisk. The self test asks it to answer, so
# without this wait the summary reports "Asterisk does not answer" for a PBX
# that was only still starting — a false FAIL in the first-boot log.
wait_for_asterisk() {
    local i
    for i in $(seq 1 30); do
        asterisk -rx "core show uptime" >/dev/null 2>&1 && return 0
        sleep 2
    done
    log "WARNING: Asterisk is still not answering 60 s after the restart"
    return 1
}
wait_for_asterisk

# --- self test --------------------------------------------------------------
log "running aipbx-selftest"
/usr/local/sbin/aipbx-selftest 2>&1 | tee /tmp/aipbx-selftest.out || true
if grep -q 'FAIL' /tmp/aipbx-selftest.out 2>/dev/null; then
    log "WARNING: a health check failed — see the FAIL line above, then Admin → Health checks"
else
    log "self test: no check failed"
fi

ensure_cron

touch "$MARKER"
log "install finished — the portal is up on the ports compose publishes"
